package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import org.bukkit.entity.Player; import org.bukkit.event.player.PlayerMoveEvent; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class FreezeService { private final ULTRASBansPlugin plugin; private final Set<UUID> frozen=ConcurrentHashMap.newKeySet(); public FreezeService(ULTRASBansPlugin p){plugin=p;} public void set(Player p,boolean v){if(v){frozen.add(p.getUniqueId());p.sendMessage(com.ultras.bans.utility.Text.c("<red>ᴜʟᴛʀᴀs</red> | You are frozen. Contact staff."));}else{frozen.remove(p.getUniqueId());p.sendMessage(com.ultras.bans.utility.Text.c("<green>✓</green> ᴜʟᴛʀᴀs | Freeze removed."));}} public boolean isFrozen(UUID u){return frozen.contains(u);} public void move(PlayerMoveEvent e){if(!isFrozen(e.getPlayer().getUniqueId())||e.getTo()==null)return;if(e.getFrom().getX()!=e.getTo().getX()||e.getFrom().getY()!=e.getTo().getY()||e.getFrom().getZ()!=e.getTo().getZ())e.setTo(e.getFrom());} }
